from ortools.linear_solver import pywraplp
import json

def solve_maintenance_scheduling():
    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        print("Failed to create solver")
        return

    INF = solver.infinity()
    M = 1000

    operations = list(range(10))
    units = [1, 2, 3]

    start = {0: 0, 1: 80, 2: 160, 3: 240, 4: 320, 5: 400, 6: 20, 7: 100, 8: 180, 9: 260}
    end = {0: 60, 1: 140, 2: 220, 3: 300, 4: 380, 5: 460, 6: 80, 7: 160, 8: 240, 9: 320}

    cost = {
        (0, 1): 20, (0, 2): 40, (0, 3): 60, (0, 4): 80, (0, 5): 100,
        (1, 2): 25, (1, 3): 45, (1, 4): 65, (1, 5): 85,
        (2, 3): 30, (2, 4): 50, (2, 5): 70,
        (3, 4): 35, (3, 5): 55,
        (4, 5): 40,
        (6, 7): 22, (6, 8): 42, (6, 9): 62,
        (7, 8): 27, (7, 9): 47,
        (8, 9): 32,
        (0, 6): 15, (1, 7): 18, (2, 8): 21, (3, 9): 24,
        (4, 6): 27, (5, 7): 30,
        (7, 2): 35, (9, 4): 45, (1, 8): 50
    }

    max_span = 480

    assign = {}
    seq = {}
    first = {}
    last = {}

    for i in operations:
        for u in units:
            assign[(i, u)] = solver.BoolVar(f"assign_{i}_{u}")

    for i in operations:
        for j in operations:
            for u in units:
                seq[(i, j, u)] = solver.BoolVar(f"seq_{i}_{j}_{u}")

    for i in operations:
        for u in units:
            first[(i, u)] = solver.BoolVar(f"first_{i}_{u}")
            last[(i, u)] = solver.BoolVar(f"last_{i}_{u}")

    unit_start = {}
    unit_end = {}
    for u in units:
        unit_start[u] = solver.NumVar(0, INF, f"unit_start_{u}")
        unit_end[u] = solver.NumVar(0, INF, f"unit_end_{u}")

    for i in operations:
        solver.Add(sum(assign[(i, u)] for u in units) == 1)

    for i in operations:
        for j in operations:
            for u in units:
                solver.Add(seq[(i, j, u)] <= assign[(i, u)])
                solver.Add(seq[(i, j, u)] <= assign[(j, u)])

    for i in operations:
        for j in operations:
            if (i, j) not in cost:
                for u in units:
                    solver.Add(seq[(i, j, u)] == 0)

    for j in operations:
        for u in units:
            solver.Add(sum(seq[(i, j, u)] for i in operations) <= 1)

    for i in operations:
        for u in units:
            solver.Add(sum(seq[(i, j, u)] for j in operations) <= 1)

    for i in operations:
        for u in units:
            solver.Add(first[(i, u)] == assign[(i, u)] - sum(seq[(j, i, u)] for j in operations))

    for i in operations:
        for u in units:
            solver.Add(last[(i, u)] == assign[(i, u)] - sum(seq[(i, j, u)] for j in operations))

    for u in units:
        solver.Add(sum(first[(i, u)] for i in operations) == 1)

    for u in units:
        solver.Add(sum(last[(i, u)] for i in operations) == 1)

    for i in operations:
        for u in units:
            solver.Add(
                sum(seq[(i, j, u)] for j in operations) + last[(i, u)] ==
                sum(seq[(j, i, u)] for j in operations) + first[(i, u)]
            )

    for i in operations:
        for j in operations:
            for u in units:
                solver.Add(end[i] - start[j] <= M * (1 - seq[(i, j, u)]))

    for i in operations:
        for u in units:
            solver.Add(unit_start[u] >= start[i] - M * (1 - first[(i, u)]))

    for i in operations:
        for u in units:
            solver.Add(unit_start[u] <= start[i] + M * (1 - first[(i, u)]))

    for i in operations:
        for u in units:
            solver.Add(unit_end[u] >= end[i] - M * (1 - last[(i, u)]))

    for i in operations:
        for u in units:
            solver.Add(unit_end[u] <= end[i] + M * (1 - last[(i, u)]))

    for u in units:
        solver.Add(unit_end[u] - unit_start[u] <= max_span)

    objective = solver.Sum(
        cost[(i, j)] * seq[(i, j, u)]
        for (i, j) in cost
        for u in units
    )
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        service_unit_assignments = {}
        for u in units:
            service_unit_assignments[u] = []
            for i in operations:
                if assign[(i, u)].solution_value() > 0.5:
                    service_unit_assignments[u].append(i)

        ordered_assignments = {}
        for u in units:
            first_op = None
            for i in operations:
                if first[(i, u)].solution_value() > 0.5:
                    first_op = i
                    break
            if first_op is not None:
                sequence = [first_op]
                current = first_op
                while True:
                    next_op = None
                    for j in operations:
                        if seq[(current, j, u)].solution_value() > 0.5:
                            next_op = j
                            break
                    if next_op is None:
                        break
                    sequence.append(next_op)
                    current = next_op
                ordered_assignments[u] = sequence
            else:
                ordered_assignments[u] = sorted(service_unit_assignments[u])

        assignment_lists = []
        for u in [1, 2, 3]:
            seq_list = ordered_assignments.get(u, service_unit_assignments[u])
            assignment_lists.append(seq_list)

        result = {
            "service_unit_assignments": assignment_lists,
            "aggregate_transition_expenditure": solver.Objective().Value()
        }
        print(json.dumps(result))
    else:
        result = {
            "service_unit_assignments": [[], [], []],
            "aggregate_transition_expenditure": 0
        }
        print(json.dumps(result))

if __name__ == "__main__":
    solve_maintenance_scheduling()
